// /spec.schema.json: the JSON Schema of a screen spec (renderer/catalogue/spec.schema.json, generated by
// renderer/tools/gen_catalogue.mjs; /schema.json names it under spec.schema), for agents that validate before they send.
import type { APIRoute } from 'astro';
import schema from '../../../renderer/catalogue/spec.schema.json';

export const GET: APIRoute = () => new Response(JSON.stringify(schema), { headers: { 'Content-Type': 'application/json' } });
